while (total > budget && live.length > 1) {
  const old = live.shift()!;
  flushed.push(old);
  total -= estimateRows(old);
}
if (live.length === 1 && estimateRows(live[0]) > budget) {
  // A single oversized item: full copy goes to scrollback now, the
  // docked region shows just its tail.
  const it = live[0];
  flushed.push(it);
  const cols = Math.max(40, (process.stdout.columns ?? 100) - 6);
  const lines = it.text.split("\n");
  const kept: string[] = [];
  let rows = 0;
  for (let i = lines.length - 1; i >= 0 && rows < budget - 2; i--) {
    rows += Math.max(1, Math.ceil(lines[i].length / cols));
    kept.unshift(lines[i]);
  }
  live = [{ ...it, id: nextId++, text: "…\n" + kept.join("\n"), tailOnly: true }];
}
const dropped = liveRef.current.filter((it) => it.tailOnly);
liveRef.current = live;
if (flushed.length > 0 || dropped.length > 0) {
  staticRef.current = [...staticRef.current, ...flushed];
  setStaticItems(staticRef.current);
}
setLiveItems(live);

